#include <iostream>
#include <string>
#include <stdexcept>

int main() {
    std::string s1 = "cat";
    std::string s2 = s1;

    s2[0] = 'r'; // "rat"
    std::cout << "s1: " << s1 << ", s2: " << s2 << "\n";

    // Range-checked access vs range-based for
    try {
        std::cout << "Char at index 1: " << s2.at(1) << "\n";
        std::cout << "Chars via range-for: ";
        for (char c : s2) {
            std::cout << c << ' ';
        }
        std::cout << "\n";
        // Intentional out of bounds test
        s2.at(10) = 'x';
    } catch (const std::out_of_range &e) {
        std::cout << "Caught exception: " << e.what() << "\n";
    }

    // Concatenation: +, +=, and append slice
    std::string s3 = s1 + "apult"; // "catapult"
    s1 += "acomb";                // "catacomb"
    std::string s4;
    s4.append(s1, 4, s1.size() - 4); // extracts from idx 4: "comb"

    std::cout << "s1: " << s1 << "\n";
    std::cout << "s3: " << s3 << "\n";
    std::cout << "s4: " << s4 << "\n";
    return 0;
}

#include <iostream>
#include <string>

int main() {
    std::string s1 = "Testing the comparison functions.";
    std::string s2 = "Hello";
    std::string s3 = "stinger";
    std::string s4 = s2;

    // 1. Relational operators vs compare()
    if (s1 > s4) {
        std::cout << "s1 > s4\n";
    }
    int res1 = s1.compare(s2);
    std::cout << "s1.compare(s2): " << (res1 > 0 ? "> 0" : "<= 0") << "\n";

    // Compare substring of s1 ("sting" at 2, 5) with s3 ("sting" at 0, 5)
    int res2 = s1.compare(2, 5, s3, 0, 5);
    std::cout << "s1.compare(2, 5, s3, 0, 5) == " << res2 << "\n";

    // 2. Substrings using substr(start, length)
    std::string sentence = "The airplane landed on time.";
    std::string part = sentence.substr(7, 5); // "plane"
    std::cout << "Extracted substr: " << part << "\n";

    // 3. Swapping strings
    std::string first = "one";
    std::string second = "two";
    first.swap(second);
    std::cout << "After swap: first=" << first << ", second=" << second << "\n";

    return 0;
}
